# cls: eff — эликсир-эффект; chg — заряд; rea — заряд-реакция; fl — метательная склянка;
#      oilw — масло оружия; oils — масло кары; salve — мазь
C = []

def E(name, lvl, cls, src, eff, base, ess, price, tox, a89="нет", conc=None, fam=None, alt=None, note=None, off=False):
    C.append(dict(name=name, lvl=lvl, cls=cls, src=src, eff=eff, base=base, ess=ess, price=price,
                  tox=tox, a89=a89, conc=conc, fam=fam, alt=alt, note=note, off=off))

